#!/usr/bin/env python3
"""Generate the embedded glyph-outline test fonts (tests/fixtures/fonts/glyph_test_fonts.h).

Two tiny original fonts (no third-party font data), one per outline flavor the
glyph pipeline must handle:

  - TrueType (glyf): quadratic Bezier outlines
  - CFF (OpenType):  cubic Bezier outlines

Both carry the same two test glyphs at 1000 units/em:

  - 'A': a solid 600x700 square -- full coverage inside, a clean box edge for
         AA-ramp checks ("solid glyph bowl").
  - 'o': a ring -- outer circle (r=280) wound one way, inner counter (r=140)
         wound the other, so nonzero-winding rasterization must leave the
         counter empty.

Regenerate with:  python3 tests/fixtures/fonts/gen_glyph_test_fonts.py   (needs fontTools)
"""

import math
from pathlib import Path

from fontTools.fontBuilder import FontBuilder
from fontTools.pens.t2CharStringPen import T2CharStringPen
from fontTools.pens.ttGlyphPen import TTGlyphPen

UPEM = 1000
ASCENT = 800
DESCENT = -200
ADVANCE = 800

SQUARE = [(100, 0), (700, 0), (700, 700), (100, 700)]
RING_CENTER = (400, 300)
RING_OUTER_R = 280
RING_INNER_R = 140


def square_path(pen):
    pen.moveTo(SQUARE[0])
    for pt in SQUARE[1:]:
        pen.lineTo(pt)
    pen.closePath()


def circle_quads(pen, cx, cy, r, clockwise):
    """Approximate a circle with 8 quadratic arcs (control radius r/cos(pi/8))."""
    n = 8
    ctrl_r = r / math.cos(math.pi / n)
    sign = -1.0 if clockwise else 1.0

    def at(radius, step):
        a = sign * 2.0 * math.pi * step / n
        return (round(cx + radius * math.cos(a)), round(cy + radius * math.sin(a)))

    pen.moveTo(at(r, 0))
    for i in range(n):
        pen.qCurveTo(at(ctrl_r, i + 0.5), at(r, i + 1))
    pen.closePath()


def circle_cubics(pen, cx, cy, r, clockwise):
    """Approximate a circle with 4 cubic arcs (kappa handles)."""
    k = 0.5522847498 * r
    sign = -1.0 if clockwise else 1.0
    quarters = [
        [(r, 0), (r, k), (k, r), (0, r)],
        [(0, r), (-k, r), (-r, k), (-r, 0)],
        [(-r, 0), (-r, -k), (-k, -r), (0, -r)],
        [(0, -r), (k, -r), (r, -k), (r, 0)],
    ]

    def at(p):
        return (round(cx + p[0]), round(cy + sign * p[1]))

    pen.moveTo(at(quarters[0][0]))
    for q in quarters:
        pen.curveTo(at(q[1]), at(q[2]), at(q[3]))
    pen.closePath()


def ring_path(pen, circle_fn):
    cx, cy = RING_CENTER
    circle_fn(pen, cx, cy, RING_OUTER_R, clockwise=False)
    circle_fn(pen, cx, cy, RING_INNER_R, clockwise=True)


def common_setup(fb, family):
    fb.setupGlyphOrder([".notdef", "A", "o"])
    fb.setupCharacterMap({ord("A"): "A", ord("o"): "o"})
    fb.setupHorizontalMetrics({".notdef": (500, 0), "A": (ADVANCE, 100), "o": (ADVANCE, 120)})
    fb.setupHorizontalHeader(ascent=ASCENT, descent=DESCENT)
    fb.setupNameTable({"familyName": family, "styleName": "Regular"})
    fb.setupOS2(sTypoAscender=ASCENT, sTypoDescender=DESCENT)
    fb.setupPost()


def build_ttf():
    fb = FontBuilder(UPEM, isTTF=True)

    def glyph(draw):
        pen = TTGlyphPen(None)
        if draw:
            draw(pen)
        return pen.glyph()

    glyphs = {
        ".notdef": glyph(None),
        "A": glyph(square_path),
        "o": glyph(lambda pen: ring_path(pen, circle_quads)),
    }
    fb.setupGlyf(glyphs)
    common_setup(fb, "EmUiGlyphTest")
    return fb


def build_cff():
    fb = FontBuilder(UPEM, isTTF=False)

    def charstring(draw, width):
        pen = T2CharStringPen(width, None)
        if draw:
            draw(pen)
        return pen.getCharString()

    charstrings = {
        ".notdef": charstring(None, 500),
        "A": charstring(square_path, ADVANCE),
        "o": charstring(lambda pen: ring_path(pen, circle_cubics), ADVANCE),
    }
    common_setup(fb, "EmUiGlyphTestCFF")
    fb.setupCFF("EmUiGlyphTestCFF-Regular", {}, charstrings, {})
    return fb


def font_bytes(fb):
    from io import BytesIO

    buf = BytesIO()
    fb.save(buf)
    return buf.getvalue()


def c_array(name, data):
    lines = [f"static const unsigned char {name}[] = {{"]
    for i in range(0, len(data), 16):
        lines.append("    " + " ".join(f"0x{b:02x}," for b in data[i : i + 16]))
    lines.append("};")
    lines.append(f"static const long {name}_size = {len(data)};")
    return "\n".join(lines)


def main():
    ttf = font_bytes(build_ttf())
    cff = font_bytes(build_cff())

    out = Path(__file__).resolve().parent / "glyph_test_fonts.h"
    header = "\n".join(
        [
            "#pragma once",
            "",
            "// Embedded glyph-outline test fonts. GENERATED by tests/fixtures/fonts/gen_glyph_test_fonts.py -- do not edit;",
            "// regenerate with `python3 tests/fixtures/fonts/gen_glyph_test_fonts.py` (needs fontTools).",
            "//",
            "// Two tiny original fonts (1000 units/em, ascent 800, descent -200), one per outline flavor:",
            "// k_glyph_test_ttf is TrueType (quadratic outlines), k_glyph_test_cff is CFF (cubic outlines).",
            "// Both map two codepoints: 'A' (solid 600x700 square at (100,0), advance 800) and 'o' (ring at",
            "// (400,300), outer r=280, counter r=140 wound opposite, advance 800).",
            "",
            c_array("k_glyph_test_ttf", ttf),
            "",
            c_array("k_glyph_test_cff", cff),
            "",
        ]
    )
    out.write_text(header)
    print(f"wrote {out} ({len(ttf)} TTF bytes, {len(cff)} CFF bytes)")


if __name__ == "__main__":
    main()
